function createUser(name, salary) {
  return {
    getName: () => name,
    getSalary: () => salary,
    raise: (amount) => { salary += amount; }
  };
}
const user = createUser('Alice', 50000);
console.log(user.getName());
user.raise(5000);
console.log(user.getSalary());
